#!/bin/bash
#SBATCH --job-name=blah
#SBATCH --output=logs/%j.out
# ADAPT IN FUNCTION OF WHICH MODELS NEED TO BE FIT. By default will fit models
# to 25 imputed datasets in total, 13 at a time
#SBATCH --array=1-25%13
#SBATCH --cpus-per-task=8
#SBATCH --mem=8G
#SBATCH --time=144:00:00

export MODELS_FILE=v3_models

# Uncomment to select which model specification to use. See the contents of the
# object generated by the prepare-modelsXXX scripts.

# M1
export MODEL_ID=5
# export MODEL_ID=13

# M2
# export MODEL_ID=57
# export MODEL_ID=65

# M3
# export MODEL_ID=31
# export MODEL_ID=39

source /home/xxx/miniconda3/etc/profile.d/conda.sh
conda activate rep2si_env

Rscript /home/xxx/rep2si/fit-imputed-models-winston.R
